// @FIGURE_CODE_BEGIN
(function () {
  var W = 1000, H = 1300;
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%').viewbox(0, 0, W, H);

  // ---- fixed layout constants (viewBox units) ----
  var Lx = 30, Rx = 970, Bottom = 1240, TLy = 10;
  var perceivedLeft = 320;
  var rBase = 70;

  // ---- mutable state ----
  var state = { skew: 25, px: 650, view: 'both' };

  // ---- layer groups (order = z-order) ----
  var gActual = draw.group().css('transition', 'opacity 0.3s');
  var gPerceived = draw.group().css('transition', 'opacity 0.3s');
  var gRays = draw.group();
  var gObjects = draw.group();
  var gLabels = draw.group();

  // actual trapezoid
  var trapPoly = gActual.polygon().fill('none').stroke({ color: '#000', width: 4, linejoin: 'round' });
  // perceived dashed rectangle
  var percRect = gPerceived.rect().fill('none').stroke({ color: '#000', width: 3, dasharray: '14,12' });

  // rays
  var rayL = gRays.line().stroke({ color: '#e00000', width: 5, linecap: 'round' });
  var rayR = gRays.line().stroke({ color: '#e00000', width: 5, linecap: 'round' });
  var rayC = gRays.line().stroke({ color: '#000', width: 1.6 });

  // objects
  var farCirc = gObjects.circle().fill('#b0b0b0').stroke({ color: '#000', width: 3 });
  var nearCirc = gObjects.circle().fill('#b0b0b0').stroke({ color: '#000', width: 3 });
  var percCirc = gObjects.circle().fill('#b8b8b8').stroke({ color: '#000', width: 3, dasharray: '10,8' });

  // pinhole marker (draggable)
  var pin = gObjects.circle(22).fill('#e00000').stroke({ color: '#000', width: 2 }).css('cursor', 'pointer');

  // labels
  function mkLabel(txt, size, anchor) {
    return gLabels.text(txt).font({ size: size || 34, family: 'Georgia, serif', anchor: anchor || 'start' }).fill('#000')
      .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 5, 'stroke-linejoin': 'round' });
  }
  var lblActual = mkLabel('Actual room floor plan', 40).font('italic');
  var lblPercRoom = mkLabel('Perceived room floor plan', 38);
  var lblPercObj1 = mkLabel('Perceived', 38, 'end');
  var lblPercObj2 = mkLabel('object', 38, 'end');
  var lblPin = mkLabel('Pinhole', 40, 'middle');

  // ---- geometry helpers ----
  function trapTopY(skew) { return TLy + skew * 21.7; }
  function farRadius(skew) { return rBase * (0.7 + (skew / 45) * 1.0); }

  function tangents(P, C, r) {
    var dx = C.x - P.x, dy = C.y - P.y;
    var dist = Math.sqrt(dx * dx + dy * dy);
    if (dist <= r) return null;
    var base = Math.atan2(dy, dx);
    var half = Math.asin(r / dist);
    var a1 = base - half, a2 = base + half;
    return [ { x: Math.cos(a1), y: Math.sin(a1) }, { x: Math.cos(a2), y: Math.sin(a2) } ];
  }
  function rayYatX(P, dir, x) {
    if (Math.abs(dir.x) < 1e-9) return null;
    var t = (x - P.x) / dir.x;
    return P.y + t * dir.y;
  }

  // ---- main update ----
  function update() {
    var skew = state.skew, TRy = trapTopY(skew);
    var P = { x: state.px, y: Bottom };

    // trapezoid
    trapPoly.plot([[Lx, TLy], [Rx, TRy], [Rx, Bottom], [Lx, Bottom]]);
    // perceived rectangle (shares right & bottom edges, top at TRy)
    percRect.attr({ x: perceivedLeft, y: TRy, width: Rx - perceivedLeft, height: Bottom - TRy });

    // far circle in top-left corner
    var rF = farRadius(skew);
    var fCx = Lx + rF + 18, fCy = TLy + rF + 40;
    farCirc.attr({ cx: fCx, cy: fCy, r: rF });

    // near circle on right wall (physically equal base size)
    var rN = rBase * 1.25;
    var nCx = Rx - rN - 28, nCy = TRy + (Bottom - TRy) * 0.32;
    nearCirc.attr({ cx: nCx, cy: nCy, r: rN });

    // rays: tangents from pinhole to far circle
    var C = { x: fCx, y: fCy };
    var tg = tangents(P, C, rF);
    var ext = 2200;
    if (tg) {
      rayL.plot([P.x, P.y, P.x + tg[0].x * ext, P.y + tg[0].y * ext]);
      rayR.plot([P.x, P.y, P.x + tg[1].x * ext, P.y + tg[1].y * ext]);
      // perceived circle = projection of angular extent onto assumed left wall (x=perceivedLeft)
      var y1 = rayYatX(P, tg[0], perceivedLeft);
      var y2 = rayYatX(P, tg[1], perceivedLeft);
      if (y1 != null && y2 != null) {
        var pcY = (y1 + y2) / 2, pcR = Math.abs(y1 - y2) / 2;
        percCirc.attr({ cx: perceivedLeft, cy: pcY, r: Math.max(6, pcR) }).show();
        lblPercObj1.attr({ x: perceivedLeft - pcR - 18, y: pcY - 6 });
        lblPercObj2.attr({ x: perceivedLeft - pcR - 18, y: pcY + 40 });
      } else { percCirc.hide(); }
    }
    // centerline ray pinhole -> far center
    var cdx = C.x - P.x, cdy = C.y - P.y, cl = Math.sqrt(cdx * cdx + cdy * cdy);
    rayC.plot([P.x, P.y, P.x + (cdx / cl) * (cl + 120), P.y + (cdy / cl) * (cl + 120)]);

    // pinhole marker
    pin.attr({ cx: P.x, cy: P.y });
    lblPin.attr({ x: P.x, y: Bottom + 50 });

    // rotated actual label along top slant
    var midX = (Lx + Rx) / 2 + 40, midY = (TLy + TRy) / 2 - 22;
    var ang = Math.atan2(TRy - TLy, Rx - Lx) * 180 / Math.PI;
    lblActual.attr({ x: midX, y: midY, transform: 'rotate(' + ang + ' ' + midX + ' ' + midY + ')' });
    // perceived room label along dashed top
    lblPercRoom.attr({ x: perceivedLeft + 60, y: TRy - 14 });

    // view cross-fade
    var showA = state.view !== 'perceived';
    var showP = state.view !== 'actual';
    gActual.attr('opacity', showA ? 1 : 0);
    gPerceived.attr('opacity', showP ? 1 : 0);
  }

  // ---- pinhole drag along bottom edge ----
  function toViewBox(evt) {
    var pt = draw.node.createSVGPoint();
    pt.x = evt.clientX; pt.y = evt.clientY;
    var m = draw.node.getScreenCTM();
    if (!m) return { x: state.px, y: Bottom };
    var inv = m.inverse();
    var p = pt.matrixTransform(inv);
    return { x: p.x, y: p.y };
  }
  var dragging = false;
  pin.on('pointerdown', function (e) {
    dragging = true; e.preventDefault();
    try { pin.node.setPointerCapture(e.pointerId); } catch (err) {}
  });
  pin.on('pointermove', function (e) {
    if (!dragging) return;
    var p = toViewBox(e);
    state.px = Math.max(Lx + 30, Math.min(Rx - 30, p.x));
    update();
  });
  pin.on('pointerup pointercancel', function () { dragging = false; });
  pin.on('mousemove', function (e) { showTooltip('Pinhole (drag me): the single designed viewpoint. Move it and the equal-angle coincidence breaks.', e); });
  pin.on('mouseleave', function () { hideTooltip(); });
  pin.on('click', function () { showPopup('The Pinhole', 'The Ames room is built for exactly one viewpoint. From this pinhole the trapezoidal floor plan projects identically to a square room, so the brain\u2019s rectangular prior misreads distance as size. Drag the pinhole and the red rays swing, destroying the illusion.'); });

  // hover tooltips on objects
  farCirc.on('mousemove', function (e) { showTooltip('Far object (top-left corner): physically equal to the near one, but much farther from the pinhole.', e); });
  farCirc.on('mouseleave', hideTooltip);
  nearCirc.on('mousemove', function (e) { showTooltip('Near object (right wall): same true size, but close to the pinhole.', e); });
  nearCirc.on('mouseleave', hideTooltip);
  percCirc.on('mousemove', function (e) { showTooltip('Perceived object: where the brain places the far object, assuming a square room \u2014 hence it looks smaller.', e); });
  percCirc.on('mouseleave', hideTooltip);

  // ---- UI handlers ----
  window.update_roomSkew = function (v) { state.skew = v; update(); };
  window.update_floorPlanView = function (v) { state.view = v; update(); };

