// @FIGURE_CODE_BEGIN
(function () {
  var W = 1000, H = 1300;
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%').viewbox(0, 0, W, H);

  // ---- fixed layout constants (viewBox units) ----
  var Lx = 30, Rx = 970, Bottom = 1240, TLy = 20;
  var perceivedLeft = 300;
  var rBase = 78;

  // ---- mutable state ----
  var state = { skew: 25, px: 640, view: 'both' };

  // ---- layer groups (z-order) ----
  var gActual = draw.group();
  var gPerceived = draw.group();
  var gRays = draw.group();
  var gPin = draw.group();

  // actual trapezoid
  var trapPoly = gActual.polygon().fill('none').stroke({ color: '#000', width: 4, linejoin: 'round' });
  // perceived dashed rectangle
  var percRect = gPerceived.rect().fill('none').stroke({ color: '#000', width: 3, dasharray: '16,13' });

  // rays
  var rayL = gRays.line().stroke({ color: '#e00000', width: 5, linecap: 'round' });
  var rayR = gRays.line().stroke({ color: '#e00000', width: 5, linecap: 'round' });
  var rayC = gRays.line().stroke({ color: '#000', width: 1.6 });

  // objects
  var farCirc = gActual.circle().fill('#b0b0b0').stroke({ color: '#000', width: 3 });
  var nearCirc = gActual.circle().fill('#b0b0b0').stroke({ color: '#000', width: 3 });
  var percCirc = gPerceived.circle().fill('#b8b8b8').stroke({ color: '#000', width: 3, dasharray: '11,9' });

  // pinhole marker (draggable)
  var pin = gPin.circle().attr({ r: 12 }).fill('#e00000').stroke({ color: '#000', width: 2 }).css('cursor', 'pointer');

  // ---- label factory (halo for readability) ----
  function mkLabel(parent, txt, size, anchor, italic) {
    var t = parent.text(txt)
      .font({ size: size || 36, family: 'Georgia, "Times New Roman", serif', anchor: anchor || 'start' })
      .fill('#000')
      .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 6, 'stroke-linejoin': 'round' });
    if (italic) t.attr({ 'font-style': 'italic' });
    return t;
  }
  var lblActual = mkLabel(gActual, 'Actual room floor plan', 42, 'middle', true);
  var lblPercRoom = mkLabel(gPerceived, 'Perceived room floor plan', 40, 'start', false);
  var lblPercObj1 = mkLabel(gPerceived, 'Perceived', 40, 'end', false);
  var lblPercObj2 = mkLabel(gPerceived, 'object', 40, 'end', false);
  var lblPin = mkLabel(gPin, 'Pinhole', 42, 'middle', false);

  // ---- geometry helpers ----
  function trapTopY(skew) { return TLy + skew * 20.5; }
  function farRadius(skew) { return rBase * (0.72 + (skew / 45) * 1.05); }

  function tangents(P, C, r) {
    var dx = C.x - P.x, dy = C.y - P.y;
    var dist = Math.sqrt(dx * dx + dy * dy);
    if (dist <= r + 1e-6) return null;
    var base = Math.atan2(dy, dx);
    var half = Math.asin(r / dist);
    return [
      { x: Math.cos(base - half), y: Math.sin(base - half) },
      { x: Math.cos(base + half), y: Math.sin(base + half) }
    ];
  }
  function rayYatX(P, dir, x) {
    if (Math.abs(dir.x) < 1e-9) return null;
    var t = (x - P.x) / dir.x;
    if (t < 0) return null;
    return P.y + t * dir.y;
  }

  // ---- main update ----
  function update() {
    var skew = state.skew, TRy = trapTopY(skew);
    var P = { x: state.px, y: Bottom };

    trapPoly.plot([[Lx, TLy], [Rx, TRy], [Rx, Bottom], [Lx, Bottom]]);
    percRect.attr({ x: perceivedLeft, y: TRy, width: Rx - perceivedLeft, height: Bottom - TRy });

    // far circle top-left
    var rF = farRadius(skew);
    var fCx = Lx + rF + 22, fCy = TLy + rF + 36;
    farCirc.attr({ cx: fCx, cy: fCy, r: rF });

    // near circle right wall (physically equal base size)
    var rN = rBase * 1.22;
    var nCx = Rx - rN - 30, nCy = TRy + (Bottom - TRy) * 0.34;
    nearCirc.attr({ cx: nCx, cy: nCy, r: rN });

    // rays: tangents from pinhole to far circle
    var C = { x: fCx, y: fCy };
    var tg = tangents(P, C, rF);
    var ext = 2400;
    if (tg) {
      rayL.plot([P.x, P.y, P.x + tg[0].x * ext, P.y + tg[0].y * ext]);
      rayR.plot([P.x, P.y, P.x + tg[1].x * ext, P.y + tg[1].y * ext]);
      var y1 = rayYatX(P, tg[0], perceivedLeft);
      var y2 = rayYatX(P, tg[1], perceivedLeft);
      if (y1 != null && y2 != null) {
        var pcY = (y1 + y2) / 2, pcR = Math.max(8, Math.abs(y1 - y2) / 2);
        percCirc.attr({ cx: perceivedLeft, cy: pcY, r: pcR }).show();
        lblPercObj1.attr({ x: perceivedLeft - pcR - 20, y: pcY - 4 }).show();
        lblPercObj2.attr({ x: perceivedLeft - pcR - 20, y: pcY + 44 }).show();
      } else {
        percCirc.hide(); lblPercObj1.hide(); lblPercObj2.hide();
      }
    }
    // centerline ray pinhole -> far center
    var cdx = C.x - P.x, cdy = C.y - P.y, cl = Math.sqrt(cdx * cdx + cdy * cdy) || 1;
    rayC.plot([P.x, P.y, P.x + (cdx / cl) * (cl + 130), P.y + (cdy / cl) * (cl + 130)]);

    // pinhole marker + label
    pin.attr({ cx: P.x, cy: P.y });
    lblPin.attr({ x: P.x, y: Bottom + 52 });

    // rotated actual label along top slant
    var midX = (Lx + Rx) / 2 + 30, midY = (TLy + TRy) / 2 - 26;
    var ang = Math.atan2(TRy - TLy, Rx - Lx) * 180 / Math.PI;
    lblActual.attr({ x: midX, y: midY, transform: 'rotate(' + ang.toFixed(2) + ' ' + midX + ' ' + midY + ')' });
    // perceived room label along dashed top
    lblPercRoom.attr({ x: perceivedLeft + 50, y: TRy - 16 });

    // view cross-fade
    var showA = state.view !== 'perceived';
    var showP = state.view !== 'actual';
    gActual.attr({ opacity: showA ? 1 : 0 });
    gPerceived.attr({ opacity: showP ? 1 : 0 });
  }

  // ---- robust client -> viewBox mapping (xMidYMid meet) ----
  function toViewBox(evt) {
    var node = draw.node;
    var rect = node.getBoundingClientRect();
    var scale = Math.min(rect.width / W, rect.height / H) || 1;
    var offX = (rect.width - W * scale) / 2;
    var offY = (rect.height - H * scale) / 2;
    var cx = (evt.clientX != null) ? evt.clientX : 0;
    var cy = (evt.clientY != null) ? evt.clientY : 0;
    return { x: (cx - rect.left - offX) / scale, y: (cy - rect.top - offY) / scale };
  }

  // ---- pinhole drag along bottom edge ----
  var dragging = false;
  pin.on('pointerdown', function (e) {
    dragging = true;
    if (e.preventDefault) e.preventDefault();
    try { pin.node.setPointerCapture(e.pointerId); } catch (err) {}
  });
  pin.on('pointermove', function (e) {
    if (!dragging) return;
    var p = toViewBox(e);
    state.px = Math.max(Lx + 40, Math.min(Rx - 40, p.x));
    update();
  });
  pin.on('pointerup pointercancel', function () { dragging = false; });
  pin.on('mousemove', function (e) { showTooltip('Pinhole (drag me): the single designed viewpoint. Move it and the equal-angle coincidence breaks.', e); });
  pin.on('mouseleave', function () { hideTooltip(); });
  pin.on('click', function () { showPopup('The Pinhole', 'The Ames room is built for exactly one viewpoint. From this pinhole the trapezoidal floor plan projects identically to a square room, so the brain\u2019s rectangular prior misreads distance as size. Drag the pinhole and the red rays swing, destroying the illusion.'); });

  // hover tooltips on objects
  farCirc.css('cursor', 'pointer');
  farCirc.on('mousemove', function (e) { showTooltip('Far object (top-left corner): physically equal to the near one, but much farther from the pinhole.', e); });
  farCirc.on('mouseleave', hideTooltip);
  farCirc.on('click', function () { showPopup('Far object', 'This circle sits in the distant corner of the trapezoid. To subtend the same visual angle as the near object it must be physically larger \u2014 yet the brain, assuming equal distance in a square room, reads it as smaller.'); });
  nearCirc.css('cursor', 'pointer');
  nearCirc.on('mousemove', function (e) { showTooltip('Near object (right wall): same true size class, but close to the pinhole.', e); });
  nearCirc.on('mouseleave', hideTooltip);
  nearCirc.on('click', function () { showPopup('Near object', 'This circle is close to the pinhole on the short right wall. Its proximity makes it subtend the same angle as the larger far object, so the two look identical from the designed viewpoint.'); });
  percCirc.css('cursor', 'pointer');
  percCirc.on('mousemove', function (e) { showTooltip('Perceived object: where the brain places the far object, assuming a square room \u2014 hence it looks smaller.', e); });
  percCirc.on('mouseleave', hideTooltip);

  // ---- UI handlers ----
  window.update_roomSkew = function (v) { state.skew = v; update(); };
  window.update_floorPlanView = function (v) { state.view = v; update(); };

  // ---- demo step player ----
  var steps = [
    { n: 'From the pinhole, the distant top-left object and the near right object subtend the same visual angle (the red rays). The brain, assuming a square room, places the far object at the dashed "Perceived object" circle and concludes it is smaller.', skew: 25, view: 'both', px: 640 },
    { n: 'Drag the skew slider up: the trapezoid becomes more extreme, the far object must grow to keep the same angular width, and the apparent size gap between the two objects widens \u2014 the stronger the deviation from a rectangle, the stronger the illusion.', skew: 42, view: 'both', px: 640 },
    { n: 'Now drag the pinhole along the bottom edge. The red rays swing, the perceived object drifts away from the square-room location, and the equal-angle coincidence is lost \u2014 proving the trick exists only for that single fixed viewpoint.', skew: 25, view: 'both', px: 430 },
    { n: 'Toggle to "Actual only" then "Perceived only" to see the real trapezoid and the assumed rectangle in isolation; the Ames room is constructed so these two very different shapes cast the same image through the pinhole.', skew: 25, view: 'actual', px: 640 }
  ];
  var cur = 0;
  function applyStep(i) {
    cur = (i + steps.length) % steps.length;
    var s = steps[cur];
    state.skew = s.skew; state.view = s.view; state.px = s.px;
    document.getElementById('roomSkewInput').value = s.skew;
    document.getElementById('roomSkewVal').value = s.skew;
    document.getElementById('floorPlanViewInput').value = s.view;
    document.getElementById('demoNarration').textContent = s.n;
    document.getElementById('stepLabel').textContent = (cur + 1) + ' / ' + steps.length;
    update();
  }
  window.nextStep = function () { applyStep(cur + 1); };
  window.prevStep = function () { applyStep(cur - 1); };

  update();
  window.__markRendered();
})();
// @FIGURE_CODE_END

